112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
115	        String address = normalizeAddress(ownerFieldsDto.getAddress());
116	        List<String> missingFields = new ArrayList<>();
117	        if (isBlank(ownerFieldsDto.getFirstName())) {
118	            missingFields.add("firstName");
119	        }
120	        if (isBlank(ownerFieldsDto.getLastName())) {
121	            missingFields.add("lastName");
122	        }
123	        if (isBlank(address)) {
124	            missingFields.add("address");
125	        }
126	        if (isBlank(ownerFieldsDto.getCity())) {
127	            missingFields.add("city");
128	        }
129	        if (isBlank(ownerFieldsDto.getTelephone())) {
130	            missingFields.add("telephone");
131	        }
132	        if (!missingFields.isEmpty()) {
133	            throw new MissingOwnerFieldsException(missingFields);
134	        }
135	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
136	        if (isTelephoneInUse(telephone)) {
137	            throw new DuplicateTelephoneException(ownerFieldsDto.getTelephone());
138	        }
139	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
140	        if (!sharesHousehold
141	            && isHouseholdInUse(ownerFieldsDto.getLastName(), address)) {
142	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), address);
143	        }
144	        if (isCityAtCapacity(ownerFieldsDto.getCity())) {
145	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
146	        }
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        owner.setAddress(address);
150	        owner.setTelephone(telephone);
151	        LocalDate effectiveDate = owner.getRegistrationDate() != null
152	            ? owner.getRegistrationDate() : LocalDate.now();
153	        LocalDate registrationDate = toBusinessDay(effectiveDate);
154	        if (isDailyRegistrationLimitReached(registrationDate)) {
155	            throw new DailyRegistrationLimitException(registrationDate);
156	        }
157	        owner.setRegistrationDate(registrationDate);
158	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
159	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
160	        if (sharesHousehold) {
161	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
162	        }
163	        this.clinicService.saveOwner(owner);
164	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
165	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
166	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
167	        headers.setLocation(UriComponentsBuilder.newInstance()
168	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
169	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
170	    }
