265	    private static boolean isBlank(String value) {
266	        return value == null || value.isBlank();
267	    }
268	
269	    /**
270	     * Normalizes a street address into the canonical form stored on and returned for a newly
271	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
272	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
273	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
274	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
275	     * value is what gets persisted, echoed back, and used for every address comparison (household
276	     * duplicate detection and the shared household identifier).
277	     *
278	     * @param rawAddress the address value as supplied by the client
279	     * @return the normalized address (possibly empty, never {@code null})
280	     */
281	    private static String normalizeAddress(String rawAddress) {
282	        if (rawAddress == null) {
283	            return "";
284	        }
285	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
286	        if (collapsed.isEmpty()) {
287	            return "";
288	        }
289	        String[] tokens = collapsed.split(" ");
290	        StringBuilder sb = new StringBuilder(collapsed.length());
291	        for (int i = 0; i < tokens.length; i++) {
292	            String token = tokens[i];
293	            switch (token) {
294	                case "ST" -> token = "STREET";
295	                case "RD" -> token = "ROAD";
296	                case "AVE" -> token = "AVENUE";
297	                default -> { }
298	            }
299	            if (i > 0) {
300	                sb.append(' ');
301	            }
302	            sb.append(token);
303	        }
304	        return sb.toString();
305	    }
306	
307	    /**
308	     * Builds the customer code assigned to a newly created owner. The code is formatted
309	     * {@code <CITY3>-<LAST3>-<NNNN>} where {@code CITY3} is the upper-cased first three letters
310	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's
311	     * last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more
312	     * than the number of owners already in that city (e.g. {@code LON-SMI-0007}).
313	     *
314	     * @param city the city of the owner being created
315	     * @param lastName the last name of the owner being created
316	     * @return the customer code to assign
317	     */
318	    private String nextCustomerCode(String city, String lastName) {
319	        String city3 = letterPrefix3(city);
320	        String last3 = letterPrefix3(lastName);
321	        String normalizedCity = normalizeIdentity(city);
322	        long sequence = this.clinicService.findAllOwners().stream()
323	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
324	            .count() + 1L;
325	        return String.format("%s-%s-%04d", city3, last3, sequence);
326	    }
327	
328	    /**
329	     * Returns the upper-cased first three letters of the given value, skipping any non-letter
330	     * characters. Values with fewer than three letters yield a shorter prefix.
331	     *
332	     * @param value the source text
333	     * @return the upper-cased letter prefix (at most three characters, never {@code null})
334	     */
335	    private static String letterPrefix3(String value) {
336	        StringBuilder prefix = new StringBuilder(3);
337	        if (value != null) {
338	            for (int i = 0; i < value.length() && prefix.length() < 3; i++) {
339	                char c = value.charAt(i);
340	                if (Character.isLetter(c)) {
341	                    prefix.append(Character.toUpperCase(c));
342	                }
343	            }
344	        }
345	        return prefix.toString();
346	    }
347	
348	    /**
349	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
350	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
351	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
352	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits.
353	     *
354	     * @param rawTelephone the telephone value as supplied by the client
355	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
356	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
357	     */
358	    private static String normalizeTelephone(String rawTelephone) {
359	        if (rawTelephone == null) {
360	            throw new InvalidTelephoneException(rawTelephone);
361	        }
362	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
363	        String e164;
364	        if (cleaned.startsWith("+")) {
365	            String digits = cleaned.substring(1);
366	            if (!digits.matches("[0-9]+")) {
367	                throw new InvalidTelephoneException(rawTelephone);
368	            }
369	            e164 = "+" + digits;
370	        } else {
371	            if (!cleaned.matches("[0-9]+")) {
372	                throw new InvalidTelephoneException(rawTelephone);
373	            }
374	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
375	            e164 = "+61" + national;
376	        }
377	        int digitCount = e164.length() - 1;
378	        if (digitCount < 8 || digitCount > 15) {
379	            throw new InvalidTelephoneException(rawTelephone);
380	        }
381	        return e164;
382	    }
