384	    /**
385	     * Determines whether any existing owner already uses the given E.164 telephone. Stored
386	     * telephones are themselves E.164, so the values are compared directly.
387	     *
388	     * @param e164Telephone the E.164 telephone of the owner being created
389	     * @return {@code true} if another owner already has the same E.164 telephone
390	     */
391	    private boolean isTelephoneInUse(String e164Telephone) {
392	        return this.clinicService.findAllOwners().stream()
393	            .map(Owner::getTelephone)
394	            .filter(existing -> existing != null)
395	            .anyMatch(e164Telephone::equals);
396	    }
397	
398	    /**
399	     * Determines whether any existing owner already shares a household with the owner being created,
400	     * i.e. has both the same last name and the same address. Both fields are compared
401	     * case-insensitively after collapsing runs of whitespace to a single space and trimming.
402	     *
403	     * @param lastName the last name of the owner being created
404	     * @param address the address of the owner being created
405	     * @return {@code true} if another owner already has the same last name and address
406	     */
407	    private boolean isHouseholdInUse(String lastName, String address) {
408	        String normalizedLastName = normalizeIdentity(lastName);
409	        String normalizedAddress = normalizeIdentity(address);
410	        return this.clinicService.findAllOwners().stream()
411	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
412	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress));
413	    }
414	
415	    /**
416	     * Counts how many existing owners already share the given first name and last name with the
417	     * owner being created. Both names are compared case-insensitively (after trimming and
418	     * collapsing runs of whitespace). The count reflects the state before the new owner is
419	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
420	     *
421	     * @param firstName the first name of the owner being created
422	     * @param lastName the last name of the owner being created
423	     * @return the number of existing owners sharing the same first and last name
424	     */
425	    private int namesakeCount(String firstName, String lastName) {
426	        String normalizedFirstName = normalizeIdentity(firstName);
427	        String normalizedLastName = normalizeIdentity(lastName);
428	        return (int) this.clinicService.findAllOwners().stream()
429	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
430	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
431	            .count();
432	    }
433	
434	    /**
435	     * The maximum number of owners permitted in a single city. Once a city already contains this
436	     * many owners it is considered full and no further owners may be created there.
437	     */
438	    private static final int CITY_CAPACITY = 50;
439	
440	    /**
441	     * Determines whether the given city has already reached its capacity, i.e. already contains
442	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
443	     * collapsing runs of whitespace to a single space and trimming.
444	     *
445	     * @param city the city of the owner being created
446	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
447	     */
448	    private boolean isCityAtCapacity(String city) {
449	        String normalizedCity = normalizeIdentity(city);
450	        long count = this.clinicService.findAllOwners().stream()
451	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
452	            .count();
453	        return count >= CITY_CAPACITY;
454	    }
455	
456	    /**
457	     * The maximum number of owners that may be created on any single day. Once this many owners
458	     * already carry a {@code registrationDate} of the current day, no further owners may be created
459	     * that day.
460	     */
461	    private static final int DAILY_REGISTRATION_LIMIT = 100;
462	
463	    /**
464	     * Determines whether the daily registration limit has already been reached, i.e. whether
465	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
466	     * their {@code registrationDate}.
467	     *
468	     * @param date the current day
469	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
470	     *         registered on the given date
471	     */
472	    /**
473	     * Rolls a registration date forward onto a business day. A date that already falls on a
474	     * weekday is returned unchanged; a Saturday or Sunday is rolled forward to the following
475	     * Monday. This adjusted date is what gets stored as the {@code registrationDate} and drives
476	     * everything derived from it (the membership number's year segment, the daily create-limit).
477	     *
478	     * @param date the effective registration date (supplied by the client or defaulted to the
479	     *             server's current date)
480	     * @return the same date if it is a weekday, otherwise the following Monday
481	     */
482	    private static LocalDate toBusinessDay(LocalDate date) {
483	        DayOfWeek dayOfWeek = date.getDayOfWeek();
484	        if (dayOfWeek == DayOfWeek.SATURDAY) {
485	            return date.plusDays(2);
486	        }
487	        if (dayOfWeek == DayOfWeek.SUNDAY) {
488	            return date.plusDays(1);
489	        }
490	        return date;
491	    }
492	
493	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
494	        long count = this.clinicService.findAllOwners().stream()
495	            .filter(existing -> date.equals(existing.getRegistrationDate()))
496	            .count();
497	        return count >= DAILY_REGISTRATION_LIMIT;
498	    }
499	
500	    /**
501	     * Assigns the owner being created to the household identified by the given last name and
502	     * address and returns the household's stable shared identifier. The identifier is derived
503	     * deterministically from the normalized last name and address, so every member of the same
504	     * household resolves to the same value regardless of creation order. Any existing member that
505	     * does not yet carry the identifier is back-filled so all household members share it.
506	     *
507	     * @param lastName the last name of the owner being created
508	     * @param address the address of the owner being created
509	     * @return the stable household identifier shared by all members of the household
510	     */
511	    private String joinHousehold(String lastName, String address) {
512	        String householdId = householdIdFor(lastName, address);
513	        String normalizedLastName = normalizeIdentity(lastName);
514	        String normalizedAddress = normalizeIdentity(address);
515	        for (Owner existing : this.clinicService.findAllOwners()) {
516	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
517	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
518	                && !householdId.equals(existing.getHouseholdId())) {
519	                existing.setHouseholdId(householdId);
520	                this.clinicService.saveOwner(existing);
521	            }
522	        }
523	        return householdId;
524	    }
525	
526	    /**
527	     * Derives the stable household identifier for a given last name and address. The value is the
528	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
529	     * address, so it is stable across calls and identical for every member of the household.
530	     *
531	     * @param lastName the last name of the household
532	     * @param address the address of the household
533	     * @return the stable household identifier
534	     */
535	    private static String householdIdFor(String lastName, String address) {
536	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
537	        try {
538	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
539	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
540	            StringBuilder sb = new StringBuilder(digest.length * 2);
541	            for (byte b : digest) {
542	                sb.append(String.format("%02x", b));
543	            }
544	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
545	        }
546	        catch (java.security.NoSuchAlgorithmException e) {
547	            throw new IllegalStateException("SHA-256 not available", e);
548	        }
549	    }
550	
551	    /**
552	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
553	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
554	     * single space, and the result is lower-cased.
555	     *
556	     * @param value the raw field value
557	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
558	     */
559	    private static String normalizeIdentity(String value) {
560	        if (value == null) {
561	            return "";
562	        }
563	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
564	    }
565	}
